<?php
require __DIR__ . '/../app/bootstrap.php'; require_login();
$id=(int)($_GET['id'] ?? $_POST['id'] ?? 0); $editing=$id>0; $item=['kind'=>'Found','title'=>'','category'=>'','description'=>'','location'=>'','event_date'=>date('Y-m-d')]; $errors=[];
if ($editing) { $q=db()->prepare('SELECT * FROM items WHERE id=? AND user_id=?'); $q->execute([$id,current_user()['id']]); $found=$q->fetch(); if (!$found) { http_response_code(404); exit('Listing not found or you do not own it.'); } $item=$found; }
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); foreach (['kind','title','category','description','location','event_date'] as $key) $item[$key]=trim((string)($_POST[$key] ?? ''));
 if (!in_array($item['kind'],['Lost','Found'],true)) $errors[]='Choose whether the item is lost or found.';
 if (mb_strlen($item['title'])<3 || mb_strlen($item['title'])>120) $errors[]='Title must be between 3 and 120 characters.';
 if (!valid_category($item['category'])) $errors[]='Choose a category from the list.';
 if (mb_strlen($item['description'])<10 || mb_strlen($item['description'])>2000) $errors[]='Description must be between 10 and 2,000 characters.';
 if (mb_strlen($item['location'])<2 || mb_strlen($item['location'])>160) $errors[]='Enter a location between 2 and 160 characters.';
 $date=DateTime::createFromFormat('Y-m-d',$item['event_date']); if (!$date || $date->format('Y-m-d')!==$item['event_date'] || $item['event_date']>date('Y-m-d')) $errors[]='Choose a valid date that is not in the future.';
 if (!$errors) { if ($editing) { $q=db()->prepare('UPDATE items SET kind=?,title=?,category=?,description=?,location=?,event_date=? WHERE id=? AND user_id=?'); $q->execute([$item['kind'],$item['title'],$item['category'],$item['description'],$item['location'],$item['event_date'],$id,current_user()['id']]); flash('Your listing has been updated.'); } else { $q=db()->prepare('INSERT INTO items (user_id,kind,title,category,description,location,event_date) VALUES (?,?,?,?,?,?,?)'); $q->execute([current_user()['id'],$item['kind'],$item['title'],$item['category'],$item['description'],$item['location'],$item['event_date']]); flash('Your listing is now on the campus board.'); } redirect('my-items.php'); }
}
page_start($editing?'Edit listing':'Post an item'); ?><section class="narrow"><a class="back-link" href="my-items.php">← Back to my items</a><div class="section-head"><div><span class="eyebrow">CAMPUS BOARD</span><h1><?= $editing?'Edit your listing':'Tell the campus community' ?></h1></div></div><form class="form-card wide-card" method="post" novalidate><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><?php if($errors): ?><div class="error-list"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?><div class="form-row"><label>Report type<select name="kind" required><option <?= $item['kind']==='Found'?'selected':'' ?>>Found</option><option <?= $item['kind']==='Lost'?'selected':'' ?>>Lost</option></select></label><label>Category<select name="category" required><option value="">Choose a category</option><?php foreach(categories() as $c): ?><option value="<?= e($c) ?>" <?= $item['category']===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select></label></div><label>Item name<input name="title" minlength="3" maxlength="120" required value="<?= e($item['title']) ?>" placeholder="e.g. Blue water bottle"></label><label>Description<textarea name="description" rows="5" minlength="10" maxlength="2000" required placeholder="Add a few identifying details. Avoid sharing private information."><?= e($item['description']) ?></textarea><small>Don’t include passwords, full ID numbers, or another person’s private contact details.</small></label><div class="form-row"><label>Where was it lost or found?<input name="location" required maxlength="160" value="<?= e($item['location']) ?>" placeholder="e.g. Main library, ground floor"></label><label>Date<input type="date" name="event_date" required max="<?= date('Y-m-d') ?>" value="<?= e($item['event_date']) ?>"></label></div><div class="form-actions"><button class="button"><?= $editing?'Save changes':'Publish listing' ?></button><a href="my-items.php" class="text-link">Cancel</a></div></form></section><?php page_end(); ?>
